"""Render a self-contained reading edition with navigation and native MathML."""
from pathlib import Path
import json,re,subprocess
R=Path(__file__).resolve().parents[1]
body=subprocess.check_output(['pandoc',str(R/'dist/STUDY_GUIDE.md'),'-f','markdown+tex_math_dollars+definition_lists','-t','html5','--math-method=mathml','--section-divs'],text=True)
glossary=dict(re.findall(r'^([^\n#][^\n]+)\n: (.+)$',(R/'docs/reference/glossary.md').read_text(),re.M))
template=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Numerical and Parallel Computing | Study reader</title><style>
:root{color-scheme:light dark;--bg:#f5f7fb;--panel:#fff;--fg:#172438;--muted:#50617a;--line:#d9e0ea;--accent:#126b92} @media(prefers-color-scheme:dark){:root{--bg:#101720;--panel:#182331;--fg:#e8eff8;--muted:#afbdd0;--line:#344357;--accent:#7ad4fa}}
*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--fg);font:17px/1.65 system-ui,sans-serif}button,input{font:inherit}a{color:var(--accent)}aside{position:fixed;inset:0 auto 0 0;width:300px;padding:24px 18px;background:var(--panel);overflow:auto;border-right:1px solid var(--line)}aside h2{font-size:20px;line-height:1.3;margin:0 0 16px}aside a{display:block;padding:5px 9px;text-decoration:none;font-size:14px;line-height:1.4;border-radius:5px}aside a[aria-current=page]{background:var(--accent);color:var(--panel)}details{margin:13px 0}summary{cursor:pointer;font-weight:600}input{width:100%;padding:8px;border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--fg)}header{margin-left:300px;padding:12px 32px;position:sticky;top:0;background:var(--panel);border-bottom:1px solid var(--line);display:flex;gap:12px;align-items:center;z-index:2}header span{flex:1;font-size:14px;color:var(--muted)}button{cursor:pointer;border:1px solid var(--line);border-radius:5px;padding:6px 11px;background:var(--panel);color:var(--fg)}main{margin-left:300px;max-width:1200px;padding:25px 54px 80px}h1{font-size:2.1rem;line-height:1.2}h2{font-size:1.5rem;margin-top:2em}h3{font-size:1.15rem}p,li{max-width:80ch}pre{padding:17px;overflow:auto;background:var(--panel);border:1px solid var(--line);border-radius:7px;font-size:14px;line-height:1.5}code{font-family:ui-monospace,monospace}table{display:block;overflow:auto;border-collapse:collapse;margin:24px 0;font-size:15px}td,th{padding:10px 13px;border:1px solid var(--line);text-align:left;min-width:110px}th{background:var(--panel)}math[display=block]{display:block;overflow:auto;margin:24px 0;padding:8px}blockquote{border-left:4px solid var(--accent);padding:4px 20px;margin-left:0}.term{display:inline;padding:0;border:0;border-bottom:1px dotted var(--accent);border-radius:0;color:inherit;background:none;font:inherit;text-align:left}.popup{position:fixed;bottom:25px;right:25px;max-width:460px;padding:20px;background:var(--panel);border:2px solid var(--accent);border-radius:9px;box-shadow:0 6px 30px #0003;z-index:5}.popup p{margin:8px 0}.mobile-menu{display:none}.muted{color:var(--muted);font-size:14px}main>hr{display:none}main>section[hidden]{display:none}
@media(max-width:850px){aside{display:none;width:285px;z-index:4;box-shadow:0 0 0 100vw #0006}body.menu aside{display:block}header{margin:0;padding:9px 12px}main{margin:0;padding:20px 22px 80px}.mobile-menu{display:block}h1{font-size:1.7rem}header span{font-size:12px}.popup{left:16px;right:16px;bottom:16px;max-width:none}}@media print{aside,header,.popup{display:none!important}main{margin:0;padding:0;max-width:none}main>section[hidden]{display:block!important}main>section{break-before:page}pre{white-space:pre-wrap}body{background:white;color:black}}
</style></head><body><aside aria-label="Course navigation"><h2>Numerical and<br>Parallel Computing</h2><p class="muted">This reader works offline. You can use the arrow keys to change lessons and select underlined terms for definitions.</p><input id="filter" type="search" placeholder="Find a lesson or phrase" aria-label="Find a lesson or phrase"><nav id="nav"></nav><p class="muted"><a href="https://github.com/arunshar/numerical-parallel-computing">You can view the source repository.</a></p></aside><header><button class="mobile-menu" id="menu" aria-label="Toggle navigation">☰</button><button id="previous" aria-label="Previous lesson">←</button><span id="progress">The complete study guide is below.</span><button id="next" aria-label="Next lesson">→</button><button onclick="window.print()">Print</button></header><main>BODY_CONTENT</main><div class="popup" id="popup" role="dialog" aria-label="Term definition" hidden><strong id="term-title"></strong><p id="term-definition"></p><button id="dismiss">Close</button></div><script>
const glossary=GLOSSARY_JSON;
const pages=Array.from(document.querySelectorAll('main>section.level1'));
const nav=document.getElementById('nav');let current=0;const groups={};
function groupFor(title){const n=parseInt(title);return Number.isNaN(n)?'References':n<=16?'Numerical methods':n<=30?'CPU and distributed computing':n<=46?'GPU computing':'Integrated capstone';}
pages.forEach((p,i)=>{const title=p.querySelector('h1').textContent;const group=i===0?'Start here':groupFor(title);if(!groups[group]){const d=document.createElement('details');d.open=true;const s=document.createElement('summary');s.textContent=group;d.appendChild(s);nav.appendChild(d);groups[group]=d;}const a=document.createElement('a');a.href='#'+p.id;a.textContent=title;a.dataset.page=i;a.onclick=e=>{e.preventDefault();show(i);};groups[group].appendChild(a);});
function defineTerms(page){if(page.dataset.defined)return;page.dataset.defined='yes';const terms=Object.keys(glossary).sort((a,b)=>b.length-a.length);const escaped=terms.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));const pattern=new RegExp('\\b('+escaped.join('|')+')\\b','gi');const lookup=Object.fromEntries(terms.map(t=>[t.toLowerCase(),t]));const used=new Set();page.querySelectorAll('p').forEach(p=>{for(const node of Array.from(p.childNodes)){if(node.nodeType!==3)continue;const text=node.textContent;pattern.lastIndex=0;let m,last=0;const fragment=document.createDocumentFragment();let changed=false;while((m=pattern.exec(text))!==null){const key=lookup[m[0].toLowerCase()];if(used.has(key))continue;used.add(key);changed=true;fragment.appendChild(document.createTextNode(text.slice(last,m.index)));const button=document.createElement('button');button.className='term';button.textContent=m[0];button.onclick=()=>{document.getElementById('term-title').textContent=key;document.getElementById('term-definition').textContent=glossary[key];document.getElementById('popup').hidden=false;};fragment.appendChild(button);last=m.index+m[0].length;}if(changed){fragment.appendChild(document.createTextNode(text.slice(last)));node.replaceWith(fragment);}}});}
function show(i){current=Math.max(0,Math.min(pages.length-1,i));pages.forEach((p,j)=>p.hidden=j!==current);nav.querySelectorAll('a').forEach(a=>{if(Number(a.dataset.page)===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('progress').textContent=(current+1)+' / '+pages.length+' · '+pages[current].querySelector('h1').textContent;document.getElementById('previous').disabled=current===0;document.getElementById('next').disabled=current===pages.length-1;document.body.classList.remove('menu');document.getElementById('popup').hidden=true;defineTerms(pages[current]);try{history.replaceState(null,'','#'+pages[current].id);localStorage.setItem('numerical-parallel-reader',pages[current].id);}catch(e){}window.scrollTo(0,0);}
document.getElementById('previous').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.getElementById('menu').onclick=()=>document.body.classList.toggle('menu');document.getElementById('dismiss').onclick=()=>document.getElementById('popup').hidden=true;
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='Escape'){document.getElementById('popup').hidden=true;document.body.classList.remove('menu');}if(['ArrowDown','ArrowRight'].includes(e.key)&&!e.altKey&&!e.ctrlKey&&!e.metaKey){e.preventDefault();show(current+1);}if(['ArrowUp','ArrowLeft'].includes(e.key)&&!e.altKey&&!e.ctrlKey&&!e.metaKey){e.preventDefault();show(current-1);}});
document.getElementById('filter').oninput=e=>{const q=e.target.value.toLowerCase();nav.querySelectorAll('a').forEach(a=>a.hidden=!pages[Number(a.dataset.page)].textContent.toLowerCase().includes(q));};
document.querySelectorAll('main a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const target=document.getElementById(decodeURIComponent(a.getAttribute('href').slice(1)));if(!target)return;const page=target.closest('main>section.level1');if(page){e.preventDefault();show(pages.indexOf(page));target.scrollIntoView();}}));
let initial='';try{initial=decodeURIComponent(location.hash.slice(1))||localStorage.getItem('numerical-parallel-reader')||'';}catch(e){}if(pages.length)show(Math.max(0,pages.findIndex(p=>p.id===initial)));
</script></body></html>'''
result=template.replace('BODY_CONTENT',body).replace('GLOSSARY_JSON',json.dumps(glossary).replace('</','<\\/'))
(R/'dist/STUDY_GUIDE.html').write_text(result)
(R/'docs/_static/STUDY_GUIDE.html').write_text(result)
print(f'Wrote offline reader with {len(glossary)} glossary definitions.')
